// Edit the schedule here. days: 0=Sunday ... 6=Saturday. Outside the windows YouTube is blocked.
const TZ = 'Asia/Jerusalem';
const ALLOW_WINDOWS = [
  { days: [0, 1, 2, 3, 4], from: '16:00', to: '17:30' },
  { days: [5], from: '10:00', to: '12:00' },
];

const now = new Date(new Date().toLocaleString('en-US', { timeZone: TZ }));
const day = now.getDay();
const minutes = now.getHours() * 60 + now.getMinutes();
const toMin = (s) => { const [h, m] = s.split(':').map(Number); return h * 60 + m; };
const allowed = ALLOW_WINDOWS.some((w) => w.days.includes(day) && minutes >= toMin(w.from) && minutes < toMin(w.to));
return [{ json: { blocked: !allowed } }];

// Same markers as the control server, so the two never leave duplicate rules behind.
const START = '! >>> youtube-guard (managed automatically - do not edit) >>>';
const END = '! <<< youtube-guard <<<';
const CLIENT = '192.168.1.50';              // IP of the Windows PC
const BLOCK = ['youtube.com', 'youtu.be', 'youtube-nocookie.com'];
const ALLOW = ['youtubekids.com', 'accounts.youtube.com'];

const blocked = $('Desired state').first().json.blocked;
const existing = $input.first().json.user_rules || [];

const rest = [];
let inside = false;
for (const line of existing) {
  if (line === START) { inside = true; continue; }
  if (line === END) { inside = false; continue; }
  if (!inside) rest.push(line);
}
while (rest.length && rest[rest.length - 1].trim() === '') rest.pop();

const managed = [START];
if (blocked) {
  for (const d of BLOCK) managed.push(`||${d}^$client=${CLIENT}`);
  for (const d of ALLOW) managed.push(`@@||${d}^$client=${CLIENT}`);
} else {
  managed.push('! state: allowed');
}
managed.push(END);

const rules = [...rest, ...managed];
if (JSON.stringify(rules) === JSON.stringify(existing)) return [];   // nothing to do
return [{ json: { rules, blocked } }];
